mapper.select:
select a.id, a.finance_number, a.serial_number, a.`name`, a.type_id, a.type_name, a.norms, a.unit, a.price, a.source_id, a.purchase_date, a.start_time, a.maintenance_date, a.maintenance_time, a.usage_time, a.usage_date, a.`status`, a.admin_id, a.area_id, a.receive_dep_id, a.receive_dep_name, a.receive_user_id, a.create_by, a.creator_id, a.creator_type, a.create_time, a.imgs, a.file, a.number, a.maintenance_dep_name, a.maintenance_dep_id, a.device_number, a.lat_and_lon, a.location, b.scene_type from property_detailed a left join property_bim_config b on a.id=b.business_id
and b.scene_type = #{param.sceneType}
a.authority='DEPOSITORY' and a.status in
#{item}
and a.id in
#{item}
and a.purchase_date=#{param.purchaseDate}
and a.start_time=#{param.startTime}
and a.receive_dep_id=#{param.receiveDepId}
and a.type_id in
#{item}
and a.source_id=#{param.sourceId}
and a.area_id like concat("%",#{param.areaId},"%")
and a.start_time between #{param.warehousingStartDate} and #{param.warehousingEndDate}
and a.purchase_date between #{param.purchaseStartDate} and #{param.purchaseEndDate}
and (a.serial_number like concat('%',#{param.keyword},'%') or a.name like concat('%',#{param.keyword},'%') )
and b.scene_type is NULL
and a.usage_date <= #{param.usageDate}
GROUP BY a.id order by a.level,a.start_time,a.id desc

