select id, `name`
from property_detailed
where depository_numbers = #{depositoryNumbers}

SELECT a.id, a.admin_id, a.name, a.receive_dep_id, a.receive_dep_name FROM property_detailed a where a.authority='DEPOSITORY' and status in ( 'LEAVE_UNUSED', 'MAKE_USE_OF', 'WEED_OUT','REPAIR_REPORT')
and a.admin_id=#{param.adminId}
and a.purchase_date=#{param.purchaseDate}
and a.receive_dep_id=#{param.receiveDepId}
and a.type_id in
#{id}
and a.area_id like concat("%",#{areaId},"%")
and a.status=#{param.status}

SELECT receive_dep_id as depId, receive_dep_name as depName, count(1) as totalNumber, sum(price) as totalPrice FROM `property_detailed` a where receive_dep_id is not null
and receive_dep_name=#{param.name}
GROUP BY receive_dep_id

select count(1) as numberTotal,sum(price) as moneyTotal
from property_detailed a

    inner join property_depository_detailed b on a.depository_numbers = b.depository_numbers


    a.authority='DEPOSITORY'
    and a.status in ('MAKE_USE_OF'
    , 'LEAVE_UNUSED'
    , 'WEED_OUT','REPAIR_REPORT')

        and a.purchase_date=#{param.purchaseDate}


        and b.start_time=#{param.startTime}


        and a.receive_dep_id=#{param.receiveDepId}


        and a.type_id=#{param.typeId}


        and a.source_id=#{param.sourceId}


        and a.status=#{param.status}


        and a.area_id=#{param.areaId}


        and a.start_time between #{param.warehousingStartDate} and #{param.warehousingEndDate}


        and a.purchase_date between #{param.purchaseStartDate} and #{param.purchaseEndDate}


        and (a.serial_number like concat('%',#{param.keyword},'%')
        or a.name like concat('%',#{param.keyword},'%')
        )


        and a.usage_date <= #{param.usageDate}

