mapper.select:
select b.id, b.serial_number, b.`name`, b.type_name, b.norms, b.unit, b.price, a.name as source_name, b.purchase_date, b.start_time, b.maintenance_date, b.maintenance_time, b.usage_time, b.usage_date, b.`status`, b.admin_id, b.area_id, b.receive_dep_id, b.receive_dep_name, b.receive_user_id, b.create_by, b.creator_id, b.creator_type, b.create_time, b.imgs as imgsStr, b.number, b.storage_location, b.maintenance_dep_name, b.maintenance_dep_id from property_detailed b left join assembly_classify a on a.id=b.source_id where authority='DEPOSITORY'
and usage_date <= #{param.maintenanceData}
and maintenance_date <= #{param.maintenanceData}
and b.status=#{param.status}
and b.type_id=#{param.typeId}
and (b.name like concat("%", #{param.keyword}, "%") or b.serial_number like concat("%", #{param.keyword}, "%"))

select count(1) as totalNumber,
IFNULL(sum(price),0) as totalPrice
from property_detailed b
where
authority='DEPOSITORY'

    and b.type_id=#{param.typeId}


    and b.status=#{param.status}


    and (b.serial_number like concat('%',#{param.keyword},'%')
    or b.name like concat('%',#{param.keyword},'%'))



        and usage_date <= #{param.maintenanceData}


        and maintenance_date <= #{param.maintenanceData}

